package com.metcoffee.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document;
@Document("usuarios") public class Usuario { @Id private String id; private String nombreUsuario,correo,password,telefono; private Rol rol=Rol.CLIENTE; public Usuario(){} public Usuario(String id,String n,String c,String p,String t,Rol r){this.id=id;nombreUsuario=n;correo=c;password=p;telefono=t;rol=r;} public String getId(){return id;} public String getNombreUsuario(){return nombreUsuario;} public String getCorreo(){return correo;} public String getPassword(){return password;} public String getTelefono(){return telefono;} public Rol getRol(){return rol;} public void setId(String v){id=v;} public void setNombreUsuario(String v){nombreUsuario=v;} public void setCorreo(String v){correo=v;} public void setPassword(String v){password=v;} public void setTelefono(String v){telefono=v;} public void setRol(Rol v){rol=v;} }
